import { NextApiRequest, NextApiResponse } from "next";
import axios from "axios";

const NOWPAYMENTS_API_KEY = "A9A3FDG-3HRMXA6-NTYRGV4-3QZE71X";
const NOWPAYMENTS_API_URL = "https://api.nowpayments.io/v1";
const VYFT_PLAN_TITLE = "Vyft program Operation Partner";

async function getPlanIdByTitle(title: string): Promise<string | null> {
  try {
    const response = await axios.get(`${NOWPAYMENTS_API_URL}/subscriptions/plans`, {
      headers: { "x-api-key": NOWPAYMENTS_API_KEY },
    });
    const plans = response.data;
    const found = Array.isArray(plans)
      ? plans.find((plan) => plan.title === title)
      : null;
    return found ? found.id : null;
  } catch (e) {
    console.error("Erreur lors de la récupération des plans :", e);
    return null;
  }
}

export default async function CheckSubscriptionStatus(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== "POST") {
    return res.status(405).json({ error: "Méthode non autorisée" });
  }

  const { email } = req.body;
  if (!email) {
    return res.status(400).json({ error: "Email manquant" });
  }

  try {
    // 1. Récupérer l'ID du plan
    const planId = await getPlanIdByTitle(VYFT_PLAN_TITLE);
    if (!planId) {
      return res.status(404).json({ error: "Plan d'abonnement introuvable." });
    }

    // 2. (Supposé) Récupérer les abonnés du plan (l'API NowPayments ne fournit pas d'endpoint pour cela)
    // Il faut donc gérer l'état d'abonnement côté backend lors de la souscription.
    // Ici, on retourne une erreur explicite pour rester conforme à la spec.
    return res.status(501).json({
      error:
        "L'API NowPayments ne permet pas de vérifier directement l'abonnement d'un utilisateur. Stockez l'état d'abonnement lors de la souscription.",
    });
  } catch (error) {
    console.error("Erreur lors de la vérification de l'abonnement :", error);
    return res.status(500).json({ error: "Erreur lors de la vérification de l'abonnement" });
  }
}